async function automatic(analyzer=model,historical=false){await service.close();config.roundAnalysis={enabled:true,historical};service=new HumanGoalService(config,analyzer);}
function complete(id='r1',outcome='turn.completed'){
 const r=registration(id);service.rounds.enroll('self',r);lines(id,[{type:'turn.started'},{type:outcome}]);service.follower.follow('self',id);return r;
}
it('opt-in terminal analysis publishes once with real bound inputs; terminal polls neither read nor grow storage',async()=>{
 const analyze=vi.spyOn(model,'analyze');await automatic();complete();await service.idle();
 let s=service.read('self');expect(analyze).toHaveBeenCalledTimes(1);expect(s.attempts[0].promoted).toBe(true);expect(s.roundAnalysis?.jobs[0].state).toBe('completed');expect(s.attempts[0].input.rounds).toBeDefined();
 const follow=vi.spyOn(service.follower,'follow'),save=vi.spyOn(service.store,'save');service.follower.poll();service.follower.poll();expect(follow).not.toHaveBeenCalled();expect(save).not.toHaveBeenCalled();
 // Explicit replay still validates the immutable prefix and retains failure.
 writeFileSync(join(evidence,'r1.jsonl'),'{"type":"turn.failed "}\n{"type":"turn.completed"}\n');expect(service.follower.follow('self','r1').status).toBe('sync-error');await service.idle();expect(analyze).toHaveBeenCalledTimes(1);
});
