async function legacyRoundProof(behaviorScope=true){
 const r=registration();service.rounds.enroll('self',r);
 service.analyze('self',{expectedGeneration:service.read('self').generation,idempotencyKey:'legacy-proof-analysis'});await service.idle();
 const s=service.read('self'),record={schema:'project-os.scoped-observation.v1',producer:'synthetic-shell',sourceHash:s.views[0].source.hash,goalHash:s.goals[0].hash,targetIds:['main'],clauseIds:['goal'],roundIds:[r.roundId],scopeSummary:'Synthetic scoped proof',limitations:['No real provider'],result:'passed' as const,behaviorScope,invocation:{kind:'shell',argv:['synthetic-check'],stdout:'passed',stderr:'',exitCode:0}},rawRecord=JSON.stringify(record),rawHash=digest(rawRecord),ref={rootIndex:0,path:'legacy.json',sha256:rawHash};
 writeFileSync(join(evidence,ref.path),rawRecord);
 const request={expectedGeneration:s.generation,idempotencyKey:`round-evidence-${rawHash.slice(0,40)}`,producer:record.producer,rawRecord,rawHash,sourceHash:record.sourceHash,goalHash:record.goalHash,targetIds:record.targetIds,clauseIds:record.clauseIds,result:record.result,trustedRecord:{rootIndex:ref.rootIndex,path:ref.path}};
 // Persist through the unchanged pre-round-6 observe protocol, not the new importer.
 const receipt=service.observe('self',request);
 expect(service.read('self').idempotency[request.idempotencyKey]).toEqual({payloadHash:hash(request),result:receipt});
 return {ref,request,receipt,record};
}
